import{_ as t,o,c as s,a2 as c}from"./chunks/framework.D7EuCHIT.js";const E=JSON.parse('{"title":"系统网页接口","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/links.md","filePath":"plugins/links.md","lastUpdated":1791906173000}'),n={name:"plugins/links.md"};function a(r,e,d,_,i,p){return o(),s("div",null,[...e[0]||(e[0]=[c('<h1 id="系统网页接口" tabindex="-1">系统网页接口 <a class="header-anchor" href="#系统网页接口" aria-label="Permalink to &quot;系统网页接口&quot;">​</a></h1><p>基准宿主 <code>3cd35fa</code> 提供 <code>system.links</code>，接口 <code>LYRA_INTERFACE_LINKS</code> 的 ID 为 <strong>20</strong>，版本 <strong>3</strong>，声明位于 <code>plugin/link_contracts.h</code>。消息接口为精确的 size/version/user/request 布局，旧接口 ID 不复用。</p><p>初始化时通过 <code>LyraServiceContextV3.lookup</code> 缓存服务句柄。调用时使用 <code>context-&gt;interface(context-&gt;user, handle, LYRA_SERVICE_SELECTED, LYRA_INTERFACE_LINKS, LYRA_INTERFACE_VERSION, sizeof(LyraLinksInterfaceV3))</code> 获取当前实现；校验接口 size/version 和 request 后调用，不跨操作保留接口指针。</p><h2 id="消息" tabindex="-1">消息 <a class="header-anchor" href="#消息" aria-label="Permalink to &quot;消息&quot;">​</a></h2><p>操作 <code>LYRA_LINK_OPEN_WEB</code> 为 <strong>1</strong>，必需字段 <code>LYRA_LINK_URI</code> 为 <strong>1</strong>，类型 <code>LYRA_FIELD_UTF8</code>。bytes 为 UTF-8 字节数，不含结尾 NUL；数据只在调用期间借用。仅支持 http 和 https scheme，不接受组件名、Intent extras 或 JavaScript URL。</p><p>实现通过系统 ACTION_VIEW 解析并打开网页。有默认浏览器时使用系统默认；未设默认项时由系统提供选择界面。宿主不会模拟系统提示。</p><p>成功为 <code>LYRA_MESSAGE_OK</code>，无平台实现、无适用应用或不支持的 scheme 返回 <code>LYRA_MESSAGE_UNSUPPORTED</code>；无 URI、重复 URI、空值、嵌入 NUL 或非法信封返回 <code>LYRA_MESSAGE_INVALID</code>。返回值同时写入 reply.status，不返回字段。未知必需字段拒绝，未知可选字段忽略。</p><p>必须在宿主帧线程、有效 Activity 生命周期内调用。插件可提供 kind 为 <code>system.links</code> 的替代实现，通过 query_interface 返回 ID 20 的当前消息接口；不需要宿主源码或新的 Host 字段。</p><p>设置中的开发者文档入口使用此能力。目标地址仍由 <code>plugin_settings.docs_url</code> 配置，入口文字由 <code>plugin_settings.docs</code> 配置。</p>',9)])])}const I=t(n,[["render",a]]);export{E as __pageData,I as default};
